// Build this week's review scoreboard.
// Every business Google showed in the local pack becomes one row, and each
// rival is scored against your own listing on review count and star rating.
const config = $('Set your business and search').first().json;
const yourName = String(config.yourBusinessName || '').trim().toLowerCase();
const weekOf = $now.toFormat('yyyy-MM-dd');

const rows = $input.all().map((item) => {
  const biz = item.json.local_results || {};
  const params = item.json.search_parameters || {};
  const title = String(biz.title || '');
  return {
    search: params.q || '',
    location: params.location || '',
    rank: biz.position ?? '',
    business: title,
    isYours: yourName !== '' && title.toLowerCase().includes(yourName),
    rating: typeof biz.rating === 'number' ? biz.rating : '',
    reviews: typeof biz.reviews === 'number' ? biz.reviews : '',
    category: biz.type || '',
    phone: biz.phone || '',
    placeId: biz.place_id || '',
  };
});

// Your own listing, if it ranked for this search. When it did not, the two
// comparison columns stay blank rather than guessing a baseline.
const you = rows.find((r) => r.isYours);
const canCompare = (r, field) =>
  you && !r.isYours && r[field] !== '' && you[field] !== '';

return rows.map((r) => ({
  json: {
    'Week of': weekOf,
    Search: r.search,
    Location: r.location,
    'Rank in pack': r.rank,
    Business: r.business,
    'Is your business': r.isYours ? 'YES' : '',
    Rating: r.rating,
    Reviews: r.reviews,
    'Reviews vs you': canCompare(r, 'reviews') ? r.reviews - you.reviews : '',
    'Rating vs you': canCompare(r, 'rating')
      ? Number((r.rating - you.rating).toFixed(1))
      : '',
    Category: r.category,
    Phone: r.phone,
    'Place ID': r.placeId,
  },
}));
